      "tools?: { description?: string; name?: string; parameters?: object; type?: 'function'; } | { server_label: string; type: 'mcp'; allowed_tools?: string[] | { read_only?: boolean; tool_names?: string[]; }; authorization?: string; connector_id?: string; headers?: object; require_approval?: { always?: object; never?: object; } | 'always' | 'never'; server_description?: string; server_url?: string; }[];",
